const cx=110, cy=110, r=88;
function pt(frac) {
  const a = frac * 2 * Math.PI - Math.PI/2;
  return [+(cx + r * Math.cos(a)).toFixed(2), +(cy + r * Math.sin(a)).toFixed(2)];
}
function slice(a0,a1) {
  const p0=pt(a0), p1=pt(a1);
  const large = (a1-a0)>0.5?1:0;
  return `M ${cx} ${cy} L ${p0[0]} ${p0[1]} A ${r} ${r} 0 ${large} 1 ${p1[0]} ${p1[1]} Z`;
}
const cuts=[0,0.42,0.58,0.71,0.80,1];
for (let i=0;i<cuts.length-1;i++) {
  const mid=(cuts[i]+cuts[i+1])/2;
  const [lx,ly]=(()=>{const a=mid*2*Math.PI-Math.PI/2; return [+(cx+(r+18)*Math.cos(a)).toFixed(1), +(cy+(r+18)*Math.sin(a)).toFixed(1)];})();
  console.log(i, slice(cuts[i],cuts[i+1]), "label", lx, ly, "mid", pt(mid));
}
'

node -e '
function sine(x0,y0,amp,lambda,cycles){
  let d=`M ${x0} ${y0}`;
  const n=cycles*24;
  for(let i=1;i<=n;i++){
    const x=x0+i*(lambda/24);
    const y=y0-amp*Math.sin(2*Math.PI*(i/24));
    d+=` L ${x.toFixed(1)} ${y.toFixed(1)}`;
  }
  return d;
}
console.log("em", sine(24,96,28,48,5));
console.log("gamma", sine(430,88,18,28,4));
console.log("uv", sine(40,72,12,22,3));
