input.contents:
:root {
  --paper: #f3eee3;
  --panel: #fffaf1;
  --ink: #1c2430;
  --muted: #5b6573;
  --rule: #d7cbb6;
  --teal: #0e5f56;
  --teal-deep: #083f3a;
  --ochre: #c47a12;
  --alpha: #c0392b;
  --beta: #1d4f91;
  --gamma: #c9a227;
  --proton: #c0392b;
  --neutron: #2f7a4a;
  --electron: #2a62a8;
  --ion-plus: #d35400;
  --ok: #1f7a45;
  --bad: #a32626;
  --lead: #2d3038;
  --al: #c5ccd4;
  --shadow: 0 10px 30px rgba(28, 36, 48, 0.08);
  font-family: "Avenir Next", "Segoe UI", "Helvetica Neue", sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  background:
    radial-gradient(1200px 500px at 10% -10%, #fff8ea 0%, transparent 60%),
    var(--paper);
  color: var(--ink);
}

body { line-height: 1.35; }

a { color: var(--teal); }

.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem 1.2rem;
  align-items: center;
  justify-content: space-between;
  padding: 0.7rem 1.2rem;
  background: var(--teal-deep);
  color: #f4efe4;
  border-bottom: 4px solid var(--ochre);
}

.brand {
  font-weight: 700;
  letter-spacing: 0.02em;
  text-decoration: none;
  color: inherit;
}

.brand small {
  display: block;
  font-weight: 500;
  opacity: 0.75;
  font-size: 0.72rem;
}

nav a {
  color: #f4efe4;
  text-decoration: none;
  font-size: 0.92rem;
  padding: 0.25rem 0.45rem;
  border-bottom: 2px solid transparent;
}

nav a[aria-current="page"],
nav a:hover { border-bottom-color: var(--ochre); }

main {
  max-width: 1080px;
  margin: 0 auto;
  padding: 1.4rem 1.1rem 4rem;
}

h1, h2, h3 {
  font-family: Palatino, "Palatino Linotype", "Iowan Old Style", Georgia, serif;
  font-weight: 600;
  letter-spacing: -0.02em;
  margin: 0 0 0.4rem;
}

h1 { font-size: clamp(1.8rem, 3vw, 2.5rem); }
h2 { font-size: 1.45rem; color: var(--teal-deep); }
h3 { font-size: 1.12rem; }

.kicker {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.72rem;
  color: var(--ochre);
  font-weight: 700;
  margin-bottom: 0.2rem;
}

.lede {
  color: var(--muted);
  max-width: 42rem;
  margin: 0 0 1.2rem;
}

.idea {
  background: var(--panel);
  border: 1px solid var(--rule);
  box-shadow: var(--shadow);
  padding: 1rem 1rem 1.15rem;
  margin: 1.35rem 0;
}

.idea header {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: baseline;
  margin-bottom: 0.7rem;
}

.stamp {
  font-size: 0.75rem;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.visual {
  background: #eef4f2;
  border: 1px solid #cfdcd6;
  min-height: 200px;
  padding: 0.6rem;
  overflow: hidden;
}

.visual svg,
.visual canvas {
  display: block;
  width: 100%;
  height: auto;
}

.caption {
  margin: 0.45rem 0 0;
  font-size: 0.88rem;
  color: var(--muted);
}

.one-liners {
  display: grid;
  gap: 0.35rem;
  margin: 0.8rem 0 0;
}

.one-liners p {
  margin: 0;
  padding-left: 0.7rem;
  border-left: 3px solid var(--teal);
}

.eq {
  font-size: 1.12rem;
  background: #f0ebe0;
  padding: 0.55rem 0.7rem;
  margin: 0.5rem 0;
  overflow-x: auto;
  font-family: Palatino, "Palatino Linotype", Georgia, serif;
}

.nuc {
  display: inline-flex;
  align-items: center;
  font-family: Palatino, "Palatino Linotype", Georgia, serif;
}

.nuc .az {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-end;
  font-size: 0.58em;
  line-height: 1.05;
  margin-right: 0.08em;
}

.row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
  margin: 0.55rem 0;
}

button, .chip {
  font: inherit;
  border: 1px solid #b9c4bc;
  background: #fff;
  color: var(--ink);
  padding: 0.32rem 0.7rem;
  cursor: pointer;
}

button:hover { border-color: var(--teal); }

button[aria-pressed="true"],
.chip.on {
  background: var(--teal);
  color: #fff;
  border-color: var(--teal);
}

.legend {
  display: flex;
  gap: 0.8rem;
  flex-wrap: wrap;
  font-size: 0.82rem;
  color: var(--muted);
}

.swatch {
  display: inline-block;
  width: 0.7rem;
  height: 0.7rem;
  margin-right: 0.25rem;
  vertical-align: -0.05rem;
}

.swatch.a { background: var(--alpha); }
.swatch.b { background: var(--beta); }
.swatch.g { background: var(--gamma); }
.swatch.p { background: var(--proton); }
.swatch.n { background: var(--neutron); }
.swatch.e { background: var(--electron); }

.check {
  margin-top: 0.9rem;
  padding-top: 0.8rem;
  border-top: 1px dashed var(--rule);
}

.check h3 { margin-bottom: 0.45rem; }

.choices { display: grid; gap: 0.4rem; }

.choices button { text-align: left; }

.choices button.correct {
  background: #e6f5ea;
  border-color: var(--ok);
}

.choices button.wrong {
  background: #fbeaea;
  border-color: var(--bad);
}

.feedback {
  min-height: 1.3em;
  margin: 0.4rem 0 0;
  font-size: 0.92rem;
}

.feedback.ok { color: var(--ok); }
.feedback.no { color: var(--bad); }

.toc {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 0.8rem;
}

.toc a {
  display: block;
  text-decoration: none;
  color: inherit;
  background: var(--panel);
  border: 1px solid var(--rule);
  padding: 0.9rem;
  min-height: 8.5rem;
}

.toc a:hover { border-color: var(--teal); }

.toc svg { width: 100%; height: 72px; }

.controls { display: flex; flex-wrap: wrap; gap: 0.4rem; margin: 0.5rem 0; }

.meter {
  font-variant-numeric: tabular-nums;
  font-family: ui-monospace, Menlo, monospace;
  background: #111;
  color: #9cffb0;
  padding: 0.2rem 0.5rem;
}

table.compact {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.92rem;
  margin-top: 0.6rem;
}

table.compact th,
table.compact td {
  border: 1px solid var(--rule);
  padding: 0.35rem 0.45rem;
  text-align: center;
}

table.compact th { background: #efe6d4; }

.pie {
  display: grid;
  grid-template-columns: minmax(220px, 240px) 1fr;
  gap: 1rem;
  align-items: center;
}

.flow {
  display: grid;
  grid-template-columns: minmax(280px, 1.15fr) minmax(240px, 0.9fr);
  gap: 0.8rem;
}

.node { cursor: pointer; }

.node rect,
.node ellipse {
  stroke: var(--ink);
  stroke-width: 1.5;
  fill: #fff;
}

.node.active rect,
.node.active ellipse {
  fill: #dff3ee;
  stroke: var(--teal);
  stroke-width: 2.4;
}

.node.done rect,
.node.done ellipse { fill: #f3e7c8; }

.node text { pointer-events: none; }

.edge {
  stroke: #6b7380;
  stroke-width: 1.7;
  fill: none;
  marker-end: url(#arrow);
}

.edge.lit {
  stroke: var(--teal);
  stroke-width: 2.5;
  marker-end: url(#arrow-lit);
}

.edge-label { font-size: 11px; fill: #5b6573; }

.badge-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.4rem;
  text-align: center;
  font-size: 0.82rem;
}

.compare td.sel { outline: 2px solid var(--teal); }
tr.on td { background: #dff3ee; }

.later {
  margin: 1.2rem 0 0;
  padding: 0.7rem 0.85rem;
  background: #eef4f2;
  border-left: 4px solid var(--teal);
  color: var(--muted);
  font-size: 0.95rem;
}

.knock .ray { transform-box: fill-box; transform-origin: left center; }
.play .knock .ray { animation: shoot 1.1s ease-out both; }
.play .knock .eject { animation: fly 1.1s 0.45s ease-out both; }
.play .knock .ion { animation: flush 0.4s 0.45s linear both; }
.play .tube .e-beam { animation: beam 1.4s linear infinite; }
.play .tube .xburst { animation: burst 1.4s ease-in infinite; }
.play .pair .e2 { animation: capture 1.2s 0.5s ease-out both; }
.play .pair .minus { animation: flush 0.4s 0.95s linear both; }
.play .decay-a .he { animation: spit-a 1.15s ease-out both; }
.play .decay-b .beta { animation: spit-b 1s ease-out both; }
.play .decay-g .wave { animation: burst 1.4s ease-out both; }
.play .gm .pair-dot { animation: gm-ion 1.2s ease-out infinite; }
.play .gm .pulse { animation: gm-pulse 1.2s ease-out infinite; }

@keyframes shoot {
  from { transform: scaleX(0); opacity: 0.2; }
  to { transform: scaleX(1); opacity: 1; }
}
@keyframes fly {
  from { opacity: 0; transform: translate(0, 0); }
  to { opacity: 1; transform: translate(92px, 42px); }
}
@keyframes capture {
  from { opacity: 0; transform: translate(0, 0); }
  to { opacity: 1; transform: translate(118px, 58px); }
}
@keyframes flush {
  from { fill: #e0a04a; }
  to { fill: #c0392b; }
}
@keyframes beam {
  from { stroke-dashoffset: 40; }
  to { stroke-dashoffset: 0; }
}
@keyframes burst {
  0% { opacity: 0; }
  35% { opacity: 1; }
  100% { opacity: 0.35; }
}
@keyframes spit-a {
  from { transform: translate(0, 0); opacity: 0; }
  to { transform: translate(96px, -18px); opacity: 1; }
}
@keyframes spit-b {
  from { transform: translate(0, 0); opacity: 0; }
  to { transform: translate(110px, 8px); opacity: 1; }
}
@keyframes gm-ion {
  0% { opacity: 0; transform: translate(0, 0); }
  40% { opacity: 1; }
  100% { opacity: 0; transform: translate(70px, 0); }
}
@keyframes gm-pulse {
  0%, 55% { opacity: 0.2; }
  70% { opacity: 1; }
  100% { opacity: 0.2; }
}

@media (max-width: 760px) {
  .flow, .pie { grid-template-columns: 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
}

(function () {
  "use strict";

  function $(sel, root) {
    return (root || document).querySelector(sel);
  }

  function $all(sel, root) {
    return Array.from((root || document).querySelectorAll(sel));
  }

  function svgEl(name, attrs) {
    var el = document.createElementNS("http://www.w3.org/2000/svg", name);
    Object.keys(attrs || {}).forEach(function (key) {
      el.setAttribute(key, String(attrs[key]));
    });
    return el;
  }

  function setFeedback(el, ok, text) {
    if (!el) return;
    el.textContent = text;
    el.className = "feedback " + (ok ? "ok" : "no");
  }

  function initMc() {
    $all("[data-check='mc']").forEach(function (box) {
      var answer = box.getAttribute("data-answer");
      var out = $(".feedback", box);
      $all("button[data-choice]", box).forEach(function (btn) {
        btn.addEventListener("click", function () {
          var pick = btn.getAttribute("data-choice");
          $all("button[data-choice]", box).forEach(function (b) {
            b.classList.remove("correct", "wrong");
            b.disabled = true;
          });
          if (pick === answer) {
            btn.classList.add("correct");
            setFeedback(out, true, "Yes.");
          } else {
            btn.classList.add("wrong");
            var right = $("button[data-choice='" + answer + "']", box);
            if (right) right.classList.add("correct");
            setFeedback(out, false, "Not this one.");
          }
        });
      });
    });
  }

  function initTf() {
    $all("[data-check='tf']").forEach(function (box) {
      $all(".tf-item", box).forEach(function (item) {
        var answer = item.getAttribute("data-answer") === "true";
        var out = $(".feedback", item);
        $all("button[data-tf]", item).forEach(function (btn) {
          btn.addEventListener("click", function () {
            var pick = btn.getAttribute("data-tf") === "true";
            $all("button[data-tf]", item).forEach(function (b) {
              b.disabled = true;
            });
            if (pick === answer) {
              btn.classList.add("correct");
              setFeedback(out, true, "Yes.");
            } else {
              btn.classList.add("wrong");
              setFeedback(out, false, answer ? "True." : "False.");
            }
          });
        });
      });
    });
  }

  function replay(el) {
    el.classList.remove("play");
    void el.offsetWidth;
    el.classList.add("play");
  }

  function initReplays() {
    $all("[data-replay]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        var target = document.getElementById(btn.getAttribute("data-replay"));
        if (target) replay(target);
      });
    });
    $all(".visual[data-autoplay]").forEach(function (v) {
      replay(v);
    });
  }

  function initSpectrum() {
    var slider = $("#spectrum-slider");
    var mark = $("#spectrum-mark");
    var label = $("#spectrum-label");
    if (!slider || !mark) return;
    var cutX = 390;
    function update() {
      var f = Number(slider.value);
      mark.setAttribute("x1", String(f));
      mark.setAttribute("x2", String(f));
      var ionizing = f >= cutX;
      label.textContent = ionizing
        ? "Ionizing: X-rays and γ (frequency higher than UV)."
        : "Non-ionizing: radio through ultraviolet.";
    }
    slider.addEventListener("input", update);
    update();
  }

  function initImaging() {
    var film = $("#xray-film");
    var shadow = $("#xray-shadow");
    var fleshRays = $("#xray-through-flesh");
    var boneBlock = $("#xray-stopped-bone");
    if (!film) return;
    function show(kind) {
      if (kind === "bone") {
        film.setAttribute("fill", "#f4efe0");
        if (shadow) shadow.setAttribute("opacity", "1");
        if (fleshRays) fleshRays.setAttribute("opacity", "0.25");
        if (boneBlock) boneBlock.setAttribute("opacity", "1");
      } else if (kind === "flesh") {
        film.setAttribute("fill", "#3d3426");
        if (shadow) shadow.setAttribute("opacity", "0");
        if (fleshRays) fleshRays.setAttribute("opacity", "1");
        if (boneBlock) boneBlock.setAttribute("opacity", "0.2");
      } else {
        film.setAttribute("fill", "#1c1812");
        if (shadow) shadow.setAttribute("opacity", "0");
        if (fleshRays) fleshRays.setAttribute("opacity", "1");
        if (boneBlock) boneBlock.setAttribute("opacity", "0");
      }
    }
    $all("[data-tissue]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        show(btn.getAttribute("data-tissue"));
      });
    });
  }

  function initAtomZoom() {
    var g = $("#atom-zoom");
    var slider = $("#atom-zoom-slider");
    if (!g || !slider) return;
    slider.addEventListener("input", function () {
      var z = Number(slider.value);
      g.setAttribute("transform", "translate(220 140) scale(" + z + ") translate(-220 -140)");
    });
  }

  function honeycomb(count) {
    var pts = [{ x: 0, y: 0 }];
    var ring = 1;
    while (pts.length < count) {
      var k;
      for (k = 0; k < 6 && pts.length < count; k += 1) {
        var j;
        for (j = 0; j < ring && pts.length < count; j += 1) {
          var angle = (k * Math.PI) / 3 + (j * Math.PI) / (3 * ring);
          pts.push({
            x: ring * Math.cos(angle),
            y: ring * Math.sin(angle)
          });
        }
      }
      ring += 1;
    }
    return pts;
  }

  function drawCluster(parent, cx, cy, protons, neutrons, spacing) {
    var items = [];
    var i;
    for (i = 0; i < protons; i += 1) items.push("#c0392b");
    for (i = 0; i < neutrons; i += 1) items.push("#2f7a4a");
    var pts = honeycomb(items.length);
    pts.forEach(function (pt, idx) {
      parent.appendChild(svgEl("circle", {
        cx: cx + pt.x * spacing,
        cy: cy + pt.y * spacing,
        r: spacing * 0.42,
        fill: items[idx]
      }));
    });
  }

  function drawShells(parent, cx, cy, electrons) {
    var inner = Math.min(2, electrons);
    var outer = Math.max(0, electrons - 2);
    function place(n, radius) {
      var i;
      for (i = 0; i < n; i += 1) {
        var angle = -Math.PI / 2 + (i * 2 * Math.PI) / n;
        parent.appendChild(svgEl("circle", {
          cx: cx + radius * Math.cos(angle),
          cy: cy + radius * Math.sin(angle),
          r: 6,
          fill: "#2a62a8"
        }));
      }
    }
    if (inner) {
      parent.appendChild(svgEl("circle", {
        cx: cx, cy: cy, r: 28, fill: "none", stroke: "#9bb6c4"
      }));
      place(inner, 28);
    }
    if (outer) {
      parent.appendChild(svgEl("circle", {
        cx: cx, cy: cy, r: 48, fill: "none", stroke: "#9bb6c4"
      }));
      place(outer, 48);
    }
  }

  function initIsotopes() {
    var nucleus = $("#iso-nucleus");
    var label = $("#iso-label");
    if (!nucleus) return;
    function draw(nNeutrons) {
      nucleus.innerHTML = "";
      drawCluster(nucleus, 200, 108, 1, nNeutrons, 14);
      var names = ["¹H  protium  N = 0", "²H  deuterium  N = 1", "³H  tritium  N = 2"];
      if (label) label.textContent = names[nNeutrons] + "  ·  Z = 1";
    }
    $all("[data-iso]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        draw(Number(btn.getAttribute("data-iso")));
      });
    });
    draw(0);
  }

  function initNuclides() {
    var stage = $("#nuclide-stage");
    var counts = $("#nuclide-counts");
    if (!stage) return;
    var data = {
      H: { a: 1, z: 1, n: 0, e: 1, name: "H" },
      He: { a: 4, z: 2, n: 2, e: 2, name: "He" },
      Li: { a: 7, z: 3, n: 4, e: 3, name: "Li" },
      C: { a: 12, z: 6, n: 6, e: 6, name: "C" }
    };
    function draw(key) {
      var d = data[key];
      stage.innerHTML = "";
      drawCluster(stage, 430, 100, d.z, d.n, 11);
      drawShells(stage, 430, 100, d.e);
      if (counts) {
        counts.innerHTML =
          '<span class="nuc"><span class="az"><span>' + d.a + "</span><span>" + d.z +
          "</span></span>" + d.name + "</span>   A = " + d.a +
          "   Z = " + d.z + "   N = " + d.n + "   electrons = " + d.e;
      }
    }
    $all("[data-nuclide]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        draw(btn.getAttribute("data-nuclide"));
      });
    });
    draw("C");
  }

  var series = [
    { el: "U", a: 238, z: 92, n: 146, kind: "α" },
    { el: "Th", a: 234, z: 90, n: 144, kind: "β" },
    { el: "Pa", a: 234, z: 91, n: 143, kind: "β" },
    { el: "U", a: 234, z: 92, n: 142, kind: "α" },
    { el: "Th", a: 230, z: 90, n: 140, kind: "α" },
    { el: "Ra", a: 226, z: 88, n: 138, kind: "α" },
    { el: "Rn", a: 222, z: 86, n: 136, kind: "α" },
    { el: "Po", a: 218, z: 84, n: 134, kind: "α" },
    { el: "Pb", a: 214, z: 82, n: 132, kind: "β" },
    { el: "Bi", a: 214, z: 83, n: 131, kind: "β" },
    { el: "Po", a: 214, z: 84, n: 130, kind: "α" },
    { el: "Pb", a: 210, z: 82, n: 128, kind: "β" },
    { el: "Bi", a: 210, z: 83, n: 127, kind: "β" },
    { el: "Po", a: 210, z: 84, n: 126, kind: "α" },
    { el: "Pb", a: 206, z: 82, n: 124, kind: "stable" }
  ];

  function initSeries() {
    var az = $("#series-az");
    var nz = $("#series-nz");
    var readout = $("#series-readout");
    if (!az || !nz) return;
    var step = 0;
    var left = 48;
    var right = 292;
    var top = 22;
    var bottom = 208;
    var zMin = 81;
    var zMax = 93;
    var aMin = 204;
    var aMax = 240;
    var nMin = 122;
    var nMax = 148;

    function xFromZ(z) {
      return left + (z - zMin) * (right - left) / (zMax - zMin);
    }
    function yFromA(a) {
      return bottom - (a - aMin) * (bottom - top) / (aMax - aMin);
    }
    function yFromN(n) {
      return bottom - (n - nMin) * (bottom - top) / (nMax - nMin);
    }

    function plot(svg, yOf, key) {
      $all(".plot", svg).forEach(function (node) { node.remove(); });
      var pts = "";
      var i;
      for (i = 0; i <= step; i += 1) {
        var nu = series[i];
        var x = xFromZ(nu.z);
        var y = yOf(key === "a" ? nu.a : nu.n);
        pts += x + "," + y + " ";
        var fill = "#8aa39c";
        if (i === step) fill = "#0e5f56";
        else if (i > 0 && series[i - 1].kind === "β") fill = "#1d4f91";
        else if (i > 0) fill = "#c0392b";
        svg.appendChild(svgEl("circle", {
          class: "plot", cx: x, cy: y, r: i === step ? 5 : 3.2, fill: fill
        }));
      }
      svg.appendChild(svgEl("polyline", {
        class: "plot",
        points: pts,
        fill: "none",
        stroke: "#6b7380",
        "stroke-width": "1.6"
      }));
    }

    function draw() {
      plot(az, yFromA, "a");
      plot(nz, yFromN, "n");
      var nu = series[step];
      var next = nu.kind === "stable" ? "stable" : "next " + nu.kind;
      readout.textContent =
        nu.el + "-" + nu.a + "   Z = " + nu.z + "   N = " + nu.n + "   ·  " + next +
        "   ·  γ would not move this point";
    }

    $("#series-next") && $("#series-next").addEventListener("click", function () {
      step = Math.min(series.length - 1, step + 1);
      draw();
    });
    $("#series-reset") && $("#series-reset").addEventListener("click", function () {
      step = 0;
      draw();
    });
    draw();
  }

  function initDecayEq() {
    $all("[data-decay]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        var kind = btn.getAttribute("data-decay");
        $all("[data-decay-panel]").forEach(function (p) {
          p.hidden = p.getAttribute("data-decay-panel") !== kind;
        });
        var vis = document.getElementById("decay-" + kind);
        if (vis) replay(vis);
      });
    });
  }

  function jitter(n) {
    return n + Math.round((Math.random() - 0.5) * 8);
  }

  function initGm() {
    var display = $("#gm-rate");
    var bgEl = $("#gm-bg");
    var corr = $("#gm-corr");
    if (!display) return;
    var bg = 1;
    var extra = 0;
    var gridOn = true;
    var picked = 0;
    var needGridOff = false;
    function applyExtra() {
      extra = gridOn && needGridOff ? 0 : picked;
    }
    function tick() {
      var shown = Math.max(0, jitter(bg + extra));
      display.textContent = String(shown);
      if (corr) corr.textContent = String(Math.max(0, shown - bg));
    }
    setInterval(tick, 700);
    tick();
    $("#gm-bg-btn") && $("#gm-bg-btn").addEventListener("click", function () {
      picked = 0;
      needGridOff = false;
      applyExtra();
    });
    $all("[data-gm-src]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        picked = Number(btn.getAttribute("data-gm-src"));
        needGridOff = btn.getAttribute("data-need-grid") === "off";
        applyExtra();
      });
    });
    $("#gm-grid") && $("#gm-grid").addEventListener("click", function () {
      gridOn = !gridOn;
      this.setAttribute("aria-pressed", gridOn ? "true" : "false");
      this.textContent = gridOn ? "plastic grid on (blocks α)" : "plastic grid off (α can enter)";
      applyExtra();
    });
    if (bgEl) bgEl.textContent = "Hong Kong typical background ≈ 1 count s⁻¹";
  }

  function initIonCurrent() {
    var needle = $("#galvo-needle");
    if (!needle) return;
    $all("[data-current]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        var ang = btn.getAttribute("data-current") === "alpha" ? -38 : -14;
        needle.setAttribute("transform", "rotate(" + ang + " 200 148)");
      });
    });
  }

  function initTracks() {
    var canvas = $("#track-canvas");
    if (!canvas || !canvas.getContext) return;
    var ctx = canvas.getContext("2d");
    var kind = "alpha";
    var t = 0;
    var running = true;

    function drawAlpha() {
      ctx.lineWidth = 6;
      ctx.strokeStyle = "#f4f0e4";
      ctx.lineCap = "round";
      var i;
      for (i = 0; i < 5; i += 1) {
        var y = 36 + i * 32;
        var length = 90 + (i % 3) * 18;
        var grow = Math.min(length, (t * 3 + i * 12) % (length + 40));
        ctx.beginPath();
        ctx.moveTo(28, y);
        ctx.lineTo(28 + grow, y);
        ctx.stroke();
      }
    }

    function drawBeta() {
      ctx.lineWidth = 1.5;
      ctx.strokeStyle = "#dfe7f2";
      var i;
      for (i = 0; i < 6; i += 1) {
        ctx.beginPath();
        var x = 28;
        var y = 30 + i * 26;
        ctx.moveTo(x, y);
        var s;
        for (s = 0; s < 22; s += 1) {
          x += 12;
          y += Math.sin(s * 1.65 + i * 0.7 + t * 0.12) * 9;
          ctx.lineTo(x, y);
        }
        ctx.stroke();
      }
    }

    function drawGamma() {
      ctx.fillStyle = "#f4f0e4";
      var i;
      for (i = 0; i < 9; i += 1) {
        var x = 50 + ((i * 53 + t * 2) % 520);
        var y = 28 + ((i * 71) % 150);
        ctx.beginPath();
        ctx.arc(x, y, 1.6, 0, Math.PI * 2);
        ctx.fill();
        if (i % 3 === 0) {
          ctx.strokeStyle = "rgba(244,240,228,0.45)";
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(x, y);
          ctx.lineTo(x + 18, y + 10);
          ctx.stroke();
        }
      }
    }

    function frame() {
      ctx.fillStyle = "#11150f";
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      if (kind === "alpha") drawAlpha();
      else if (kind === "beta") drawBeta();
      else drawGamma();
      t += 1;
      if (running) requestAnimationFrame(frame);
    }

    $all("[data-track]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        kind = btn.getAttribute("data-track");
      });
    });
    frame();
  }

  var sources = {
    abg: { a: 200, b: 385, g: 254, label: "α + β + γ" },
    bg: { a: 0, b: 385, g: 254, label: "β + γ" },
    ag: { a: 150, b: 0, g: 254, label: "α + γ" }
  };

  function absorberCount(src, paper, al, pb, bg) {
    var count = bg;
    var alphaStopped = paper || al || pb;
    var betaStopped = al || pb;
    if (src.a && !alphaStopped) count += src.a;
    if (src.b && !betaStopped) count += src.b;
    if (src.g) count += pb ? src.g / 2 : src.g;
    return Math.max(bg, Math.round(count));
  }

  function setRay(id, x2, faded) {
    var el = document.getElementById(id);
    if (!el) return;
    el.setAttribute("x2", String(x2));
    el.setAttribute("opacity", faded ? "0.35" : "1");
    if (id === "ray-g") {
      el.setAttribute("stroke-dasharray", faded ? "6 5" : "0");
    }
  }

  function initAbsorbers() {
    var rateEl = $("#abs-rate");
    var note = $("#abs-note");
    if (!rateEl) return;
    var src = sources.bg;
    var paper = false;
    var al = false;
    var pb = false;
    var bg = 61;
    var paperX = 250;
    var alX = 330;
    var pbX = 430;
    var gmX = 560;

    function stopX(kind) {
      if (kind === "a") {
        if (paper) return paperX;
        if (al) return alX;
        if (pb) return pbX;
        return gmX;
      }
      if (kind === "b") {
        if (al) return alX;
        if (pb) return pbX;
        return gmX;
      }
      return gmX;
    }

    function render() {
      var r = jitter(absorberCount(src, paper, al, pb, bg));
      rateEl.textContent = r + " cpm";
      var bits = [];
      if (paper) bits.push("paper");
      if (al) bits.push("5 mm Al");
      if (pb) bits.push("25 mm Pb");
      if (note) {
        note.textContent = src.label + (bits.length ? "  ·  " + bits.join(", ") : "  ·  air only") +
          "  ·  background ≈ " + bg + " cpm";
      }
      setRay("ray-a", src.a ? stopX("a") : 90, !src.a);
      setRay("ray-b", src.b ? stopX("b") : 90, !src.b);
      setRay("ray-g", src.g ? stopX("g") : 90, !src.g || pb);
      var paperSlab = $("#slab-paper");
      var alSlab = $("#slab-al");
      var pbSlab = $("#slab-pb");
      if (paperSlab) paperSlab.setAttribute("opacity", paper ? "1" : "0.22");
      if (alSlab) alSlab.setAttribute("opacity", al ? "1" : "0.22");
      if (pbSlab) pbSlab.setAttribute("opacity", pb ? "1" : "0.22");
    }

    $all("[data-src]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        src = sources[btn.getAttribute("data-src")];
        render();
      });
    });
    $("#abs-paper") && $("#abs-paper").addEventListener("click", function () {
      paper = !paper;
      this.setAttribute("aria-pressed", paper ? "true" : "false");
      render();
    });
    $("#abs-al") && $("#abs-al").addEventListener("click", function () {
      al = !al;
      this.setAttribute("aria-pressed", al ? "true" : "false");
      render();
    });
    $("#abs-pb") && $("#abs-pb").addEventListener("click", function () {
      pb = !pb;
      this.setAttribute("aria-pressed", pb ? "true" : "false");
      render();
    });
    render();
  }

  var flowSteps = [
    { id: "0", text: "Unknown source in front of a GM tube. Subtract background later." },
    { id: "1", text: "Insert paper. Significant drop → α present. No drop → no α." },
    { id: "2", text: "Example: air 700 → paper 700. No α. Continue to aluminium." },
    { id: "3", text: "Insert ~5 mm Al. Drop from the paper reading → β present." },
    { id: "4", text: "Example: 700 → 315. β is present. Continue to lead." },
    { id: "5", text: "Insert ~25 mm Pb. Drop, but still above background → γ present." },
    { id: "6", text: "Example: 315 → 190 (background ≈ 61). γ is halved, not zero." },
    { id: "7", text: "Confirm: E or B splits α / β; γ straight. Tracks: thick / thin / faint." }
  ];

  function initFlow() {
    var svg = $("#id-flow");
    var talk = $("#flow-talk");
    if (!svg) return;
    var i = 0;
    var hasAlpha = false;

    function show() {
      $all(".node", svg).forEach(function (n) {
        n.classList.remove("active", "done");
        var id = n.getAttribute("data-step");
        if (id === "alpha") {
          if (hasAlpha) n.classList.add(i <= 2 ? "active" : "done");
          return;
        }
        var idx = Number(id);
        if (idx < i) n.classList.add("done");
        if (idx === i) n.classList.add("active");
      });
      $all(".edge", svg).forEach(function (e) {
        var until = Number(e.getAttribute("data-until"));
        var side = e.getAttribute("data-side");
        var lit = i >= until;
        if (side === "alpha") lit = hasAlpha && i >= 1;
        if (side === "no-alpha") lit = !hasAlpha && i >= 2;
        e.classList.toggle("lit", lit);
      });
      if (talk) talk.textContent = flowSteps[i].text;
    }

    $("#flow-next") && $("#flow-next").addEventListener("click", function () {
      i = Math.min(flowSteps.length - 1, i + 1);
      if (i >= 2) hasAlpha = hasAlpha && true;
      show();
    });
    $("#flow-reset") && $("#flow-reset").addEventListener("click", function () {
      i = 0;
      hasAlpha = false;
      show();
    });
    $all(".node", svg).forEach(function (n) {
      n.addEventListener("click", function () {
        var id = n.getAttribute("data-step");
        if (id === "alpha") {
          hasAlpha = true;
          i = 1;
          show();
          return;
        }
        var idx = Number(id);
        if (idx <= 1) hasAlpha = false;
        if (idx >= 2 && id !== "alpha") hasAlpha = hasAlpha && idx > 1 ? hasAlpha : false;
        if (idx >= 2 && !hasAlpha) hasAlpha = false;
        i = idx;
        show();
      });
    });
    show();
  }

  function initFields() {
    var eAlpha = $("#e-alpha");
    var eBeta = $("#e-beta");
    var bAlpha = $("#b-alpha");
    var bBeta = $("#b-beta");
    var flip = $("#b-flip");
    if (!eAlpha) return;
    var into = true;

    function setB() {
      var a = into
        ? "M 48 110 C 150 110 210 62 318 40"
        : "M 48 110 C 150 110 210 158 318 180";
      var b = into
        ? "M 48 110 C 120 110 138 188 236 204"
        : "M 48 110 C 120 110 138 32 236 16";
      if (bAlpha) bAlpha.setAttribute("d", a);
      if (bBeta) bBeta.setAttribute("d", b);
      $all("[data-b-mark]").forEach(function (t) {
        t.textContent = into ? "×  B into the page" : "·  B out of the page";
      });
    }

    if (flip) {
      flip.addEventListener("click", function () {
        into = !into;
        setB();
      });
    }
    setB();

    var t = 0;
    function bounce() {
      t += 0.05;
      if (eAlpha) eAlpha.setAttribute("stroke-dashoffset", String(-t * 18));
      if (eBeta) eBeta.setAttribute("stroke-dashoffset", String(-t * 28));
      if (bAlpha) bAlpha.setAttribute("stroke-dashoffset", String(-t * 18));
      if (bBeta) bBeta.setAttribute("stroke-dashoffset", String(-t * 28));
      requestAnimationFrame(bounce);
    }
    bounce();
  }

  function initBadge() {
    var open = $("#badge-open");
    var al = $("#badge-al");
    var pb = $("#badge-pb");
    if (!open) return;
    function paint(el, tone, label) {
      el.setAttribute("fill", tone);
      var text = document.getElementById(el.id + "-text");
      if (text) text.textContent = label;
    }
    $all("[data-badge]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        var kind = btn.getAttribute("data-badge");
        if (kind === "alpha") {
          paint(open, "#e7d9b3", "α stopped by wrap");
          paint(al, "#f2ead2", "");
          paint(pb, "#f2ead2", "");
        } else if (kind === "beta") {
          paint(open, "#3a3428", "open window");
          paint(al, "#e7d9b3", "Al stops β");
          paint(pb, "#f2ead2", "");
        } else {
          paint(open, "#8a7b5d", "γ");
          paint(al, "#8a7b5d", "γ");
          paint(pb, "#8a7b5d", "γ");
        }
      });
    });
  }

  function initCompare() {
    $all("[data-compare]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        var row = btn.getAttribute("data-compare");
        $all("tr[data-row]").forEach(function (tr) {
          tr.classList.toggle("on", tr.getAttribute("data-row") === row);
        });
      });
    });
  }

  document.addEventListener("DOMContentLoaded", function () {
    initMc();
    initTf();
    initReplays();
    initSpectrum();
    initImaging();
    initAtomZoom();
    initIsotopes();
    initNuclides();
    initSeries();
    initDecayEq();
    initGm();
    initIonCurrent();
    initTracks();
    initAbsorbers();
    initFlow();
    initFields();
    initBadge();
    initCompare();
  });
})();

