function honeycomb(count) {
  var coords = [];
  var span = 4;
  var q;
  for (q = -span; q <= span; q += 1) {
    var r;
    for (r = -span; r <= span; r += 1) {
      var s = -q - r;
      if (Math.max(Math.abs(q), Math.abs(r), Math.abs(s)) <= span) {
        coords.push({
          x: q + r / 2,
          y: r * Math.sqrt(3) / 2,
          order: q * q + r * r + s * s
        });
      }
    }
  }
  coords.sort(function (a, b) { return a.order - b.order; });
  return coords.slice(0, count);
}

