(function (global) {
  "use strict";

  var THREE = global.THREE;
  var scenes = {};

  function clamp01(t) {
    return Math.max(0, Math.min(1, t));
  }

  function lerp(a, b, t) {
    return a + (b - a) * t;
  }

  function smoothstep(t) {
    var u = clamp01(t);
    return u * u * (3 - 2 * u);
  }

  function ball(radius, hex) {
    var mesh = new THREE.Mesh(
      new THREE.SphereGeometry(radius, 24, 16),
      new THREE.MeshStandardMaterial({
        color: hex,
        roughness: 0.45,
        metalness: 0.08,
        transparent: true,
        opacity: 1
      })
    );
    return mesh;
  }

  function ring(radius, hex) {
    var mesh = new THREE.Mesh(
      new THREE.TorusGeometry(radius, 0.035, 10, 64),
      new THREE.MeshStandardMaterial({ color: hex, roughness: 0.6, transparent: true, opacity: 0.85 })
    );
    mesh.rotation.x = Math.PI / 2;
    return mesh;
  }

  function stage(canvas) {
    var scene = new THREE.Scene();
    scene.background = new THREE.Color(0xfffaf1);
    var camera = new THREE.OrthographicCamera(-7.2, 7.2, 3.6, -3.6, 0.1, 40);
    camera.position.set(0.4, 1.6, 12);
    camera.lookAt(0, 0, 0);
    var renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: false });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    scene.add(new THREE.AmbientLight(0xffffff, 0.7));
    var key = new THREE.DirectionalLight(0xfff4e0, 0.9);
    key.position.set(-4, 6, 8);
    scene.add(key);
    var fill = new THREE.DirectionalLight(0x9bb6c4, 0.35);
    fill.position.set(6, -2, 4);
    scene.add(fill);
    function resize() {
      var w = canvas.clientWidth || canvas.width;
      var h = canvas.clientHeight || canvas.height;
      renderer.setSize(w, h, false);
      var aspect = w / Math.max(h, 1);
      var halfH = 3.6;
      var halfW = halfH * aspect;
      camera.left = -halfW;
      camera.right = halfW;
      camera.top = halfH;
      camera.bottom = -halfH;
      camera.updateProjectionMatrix();
    }
    resize();
    window.addEventListener("resize", resize);
    return { scene: scene, camera: camera, renderer: renderer, resize: resize };
  }

  function placeHud(el, canvas, camera, world) {
    if (!el) return;
    var v = world.clone().project(camera);
    var x = (v.x * 0.5 + 0.5) * canvas.clientWidth;
    var y = (-v.y * 0.5 + 0.5) * canvas.clientHeight;
    el.style.left = x + "px";
    el.style.top = y + "px";
  }

  function hostReplay(host, restart) {
    host.addEventListener("notes-replay", restart);
    if (host.hasAttribute("data-autoplay") || host.classList.contains("play")) {
      restart();
    }
  }

  function knockout(host) {
    var canvas = host.querySelector("canvas");
    var gfx = stage(canvas);
    var SHELL_R = 1.35;
    var nucleus = ball(0.42, 0xe0a04a);
    var orbit = ring(SHELL_R, 0x9bb6c4);
    var electron = ball(0.18, 0x2a62a8);
    var plus = ball(0.12, 0xffffff);
    plus.visible = false;
    var ray = new THREE.Mesh(
      new THREE.CylinderGeometry(0.07, 0.07, 5.4, 12),
      new THREE.MeshStandardMaterial({ color: 0xc9a227, roughness: 0.4 })
    );
    ray.rotation.z = Math.PI / 2;
    var HIT_T = 0.85;
    var FLY_T = 1.15;
    var start = new THREE.Vector3(-SHELL_R, 0, 0);
    var end = new THREE.Vector3(4.4, -2.05, 0.2);
    electron.position.copy(start);
    ray.position.set(-3.9, 0, 0);
    gfx.scene.add(orbit, nucleus, plus, electron, ray);
    var hudAtom = host.querySelector('[data-hud="atom"]');
    var hudElectron = host.querySelector('[data-hud="electron"]');
    var hudRay = host.querySelector('[data-hud="ray"]');
    var t0 = performance.now();
    var reduced = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    function snapshot() {
      return {
        electronOpacity: electron.material.opacity,
        distToNucleus: electron.position.length(),
        shellRadius: SHELL_R,
        nucleusHex: "#" + nucleus.material.color.getHexString(),
        atomLabel: hudAtom ? hudAtom.textContent : "",
        electronLabel: hudElectron ? hudElectron.textContent : ""
      };
    }

    function restart() {
      t0 = performance.now();
    }

    function frame(now) {
      var t = reduced ? HIT_T + FLY_T : (now - t0) / 1000;
      var hit = clamp01(t / HIT_T);
      ray.scale.set(1, lerp(0.04, 1, smoothstep(hit)), 1);
      ray.position.x = lerp(-6.2, -3.9, smoothstep(hit));
      var fly = smoothstep((t - HIT_T) / FLY_T);
      electron.material.opacity = 1;
      electron.position.lerpVectors(start, end, fly);
      var ionized = fly > 0.02;
      nucleus.material.color.setHex(ionized ? 0xc0392b : 0xe0a04a);
      plus.visible = ionized;
      plus.position.set(0, 0, 0.45);
      if (hudAtom) hudAtom.textContent = ionized ? "positive ion" : "atom";
      placeHud(hudAtom, canvas, gfx.camera, nucleus.position.clone().add(new THREE.Vector3(0, -1.85, 0)));
      placeHud(hudElectron, canvas, gfx.camera, electron.position.clone().add(new THREE.Vector3(0.15, -0.45, 0)));
      placeHud(hudRay, canvas, gfx.camera, new THREE.Vector3(-5.2, 1.55, 0));
      gfx.renderer.render(gfx.scene, gfx.camera);
      requestAnimationFrame(frame);
    }

    hostReplay(host, restart);
    requestAnimationFrame(frame);
    scenes.knockout = { snapshot: snapshot, replay: restart };
  }

  function ionpair(host) {
    var canvas = host.querySelector("canvas");
    var gfx = stage(canvas);
    var SHELL_R = 0.95;
    var aPos = new THREE.Vector3(-2.6, 0.85, 0);
    var bPos = new THREE.Vector3(2.35, -1.15, 0);
    var nucleusA = ball(0.32, 0xe0a04a);
    var nucleusB = ball(0.32, 0xe0a04a);
    nucleusA.position.copy(aPos);
    nucleusB.position.copy(bPos);
    var orbitA = ring(SHELL_R, 0x9bb6c4);
    var orbitB = ring(SHELL_R, 0x9bb6c4);
    orbitA.position.copy(aPos);
    orbitB.position.copy(bPos);
    var electron = ball(0.16, 0x2a62a8);
    var start = aPos.clone().add(new THREE.Vector3(-SHELL_R, 0, 0));
    var finish = bPos.clone().add(new THREE.Vector3(-0.2, 0.15, 0.35));
    electron.position.copy(start);
    var ray = new THREE.Mesh(
      new THREE.CylinderGeometry(0.06, 0.06, 3.6, 12),
      new THREE.MeshStandardMaterial({ color: 0xc9a227 })
    );
    ray.rotation.z = Math.PI / 2;
    gfx.scene.add(orbitA, orbitB, nucleusA, nucleusB, electron, ray);
    var hudA = host.querySelector('[data-hud="a"]');
    var hudB = host.querySelector('[data-hud="b"]');
    var HIT_T = 0.7;
    var FLY_T = 1.05;
    var t0 = performance.now();
    var reduced = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    function snapshot() {
      return {
        electronOpacity: electron.material.opacity,
        distToA: electron.position.distanceTo(aPos),
        distToB: electron.position.distanceTo(bPos),
        shellRadius: SHELL_R,
        plusHex: "#" + nucleusA.material.color.getHexString(),
        minusHex: "#" + nucleusB.material.color.getHexString(),
        labelA: hudA ? hudA.textContent : "",
        labelB: hudB ? hudB.textContent : ""
      };
    }

    function restart() {
      t0 = performance.now();
    }

    function frame(now) {
      var t = reduced ? HIT_T + FLY_T : (now - t0) / 1000;
      var hit = smoothstep(t / HIT_T);
      ray.scale.set(1, lerp(0.05, 1, hit), 1);
      ray.position.set(lerp(-6.1, -4.1, hit), aPos.y, 0);
      var fly = smoothstep((t - HIT_T) / FLY_T);
      electron.material.opacity = 1;
      electron.position.lerpVectors(start, finish, fly);
      var plus = fly > 0.02;
      var minus = fly > 0.92;
      nucleusA.material.color.setHex(plus ? 0xc0392b : 0xe0a04a);
      nucleusB.material.color.setHex(minus ? 0x2a62a8 : 0xe0a04a);
      if (hudA) hudA.textContent = plus ? "+ ion" : "atom";
      if (hudB) hudB.textContent = minus ? "− ion" : "atom";
      placeHud(hudA, canvas, gfx.camera, aPos.clone().add(new THREE.Vector3(0, -1.45, 0)));
      placeHud(hudB, canvas, gfx.camera, bPos.clone().add(new THREE.Vector3(0, -1.45, 0)));
      gfx.renderer.render(gfx.scene, gfx.camera);
      requestAnimationFrame(frame);
    }

    hostReplay(host, restart);
    requestAnimationFrame(frame);
    scenes.ionpair = { snapshot: snapshot, replay: restart };
  }

  function atom(host) {
    var canvas = host.querySelector("canvas");
    var gfx = stage(canvas);
    gfx.camera.position.set(2.2, 2.4, 10);
    gfx.camera.lookAt(0, 0, 0);
    var nucleus = new THREE.Group();
    [[-0.16, 0.08, 0, 0xc0392b], [0.16, 0.08, 0, 0x2f7a4a], [-0.08, -0.14, 0.1, 0x2f7a4a], [0.1, -0.12, -0.1, 0xc0392b]].forEach(function (p) {
      var n = ball(0.14, p[3]);
      n.position.set(p[0], p[1], p[2]);
      nucleus.add(n);
    });
    var e1 = ball(0.11, 0x2a62a8);
    var e2 = ball(0.11, 0x2a62a8);
    var e3 = ball(0.11, 0x2a62a8);
    var inner = ring(1.15, 0x9bb6c4);
    var outer = ring(2.05, 0x9bb6c4);
    outer.rotation.y = 0.5;
    gfx.scene.add(nucleus, inner, outer, e1, e2, e3);
    var slider = document.getElementById("atom-zoom-slider");
    var angle = 0;
    function frame() {
      angle += 0.01;
      e1.position.set(Math.cos(angle) * 1.15, Math.sin(angle) * 1.15, 0);
      e2.position.set(Math.cos(angle + 2.1) * 2.05, 0.2, Math.sin(angle + 2.1) * 2.05);
      e3.position.set(Math.cos(-angle + 4) * 2.05, -0.15, Math.sin(-angle + 4) * 2.05);
      var z = slider ? Number(slider.value) : 1;
      gfx.camera.position.set(2.2 / z, 2.4 / z, Math.max(3.2, 10 / z));
      gfx.camera.lookAt(0, 0, 0);
      gfx.renderer.render(gfx.scene, gfx.camera);
      requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
    scenes.atom = {};
  }

  function tube(host) {
    var canvas = host.querySelector("canvas");
    var gfx = stage(canvas);
    var glass = new THREE.Mesh(
      new THREE.SphereGeometry(3.4, 32, 18, 0, Math.PI * 2, 0.35, 2.45),
      new THREE.MeshStandardMaterial({ color: 0xe8eef2, transparent: true, opacity: 0.22, roughness: 0.2 })
    );
    glass.scale.set(1.55, 0.72, 0.72);
    var cathode = new THREE.Mesh(
      new THREE.BoxGeometry(0.35, 1.1, 0.5),
      new THREE.MeshStandardMaterial({ color: 0x555555 })
    );
    cathode.position.set(-3.2, 0, 0);
    var target = new THREE.Mesh(
      new THREE.ConeGeometry(0.85, 1.6, 4),
      new THREE.MeshStandardMaterial({ color: 0x8a9098, metalness: 0.4, roughness: 0.35 })
    );
    target.rotation.z = -Math.PI / 2;
    target.position.set(1.7, 0, 0);
    gfx.scene.add(glass, cathode, target);
    var electrons = [];
    var i;
    for (i = 0; i < 10; i += 1) {
      var e = ball(0.1, 0x2a62a8);
      electrons.push({ mesh: e, delay: i * 0.12 });
      gfx.scene.add(e);
    }
    var xrays = [];
    for (i = 0; i < 3; i += 1) {
      var ray = new THREE.Mesh(
        new THREE.CylinderGeometry(0.04, 0.04, 2.8, 8),
        new THREE.MeshStandardMaterial({ color: 0xc9a227, transparent: true, opacity: 0.85 })
      );
      ray.position.set(3.1, -0.4 - i * 0.45, 0.2 * i);
      ray.rotation.z = Math.PI / 2 + 0.35 + i * 0.12;
      xrays.push(ray);
      gfx.scene.add(ray);
    }
    var t0 = performance.now();
    function restart() {
      t0 = performance.now();
    }
    function frame(now) {
      var t = (now - t0) / 1000;
      electrons.forEach(function (item) {
        var u = ((t * 0.55 + item.delay) % 1);
        item.mesh.position.set(lerp(-2.9, 1.15, u), Math.sin(t * 6 + item.delay) * 0.05, 0);
        item.mesh.material.opacity = 1;
        item.mesh.visible = u < 0.98;
      });
      xrays.forEach(function (ray, idx) {
        ray.material.opacity = 0.35 + 0.5 * Math.abs(Math.sin(t * 3 + idx));
      });
      gfx.renderer.render(gfx.scene, gfx.camera);
      requestAnimationFrame(frame);
    }
    hostReplay(host, restart);
    requestAnimationFrame(frame);
    scenes.tube = { replay: restart };
  }

  function nucleonCluster(protons, neutrons, spacing) {
    var group = new THREE.Group();
    var colors = [];
    var i;
    for (i = 0; i < protons; i += 1) colors.push(0xc0392b);
    for (i = 0; i < neutrons; i += 1) colors.push(0x2f7a4a);
    colors.forEach(function (hex, idx) {
      var q = (idx % 3) - 1;
      var r = Math.floor(idx / 3) - 1;
      var n = ball(0.16, hex);
      n.position.set(q * spacing, r * spacing * 0.86, ((idx * 17) % 5 - 2) * 0.08);
      group.add(n);
    });
    return group;
  }

  function decayAlpha(host) {
    var canvas = host.querySelector("canvas");
    var gfx = stage(canvas);
    var parent = nucleonCluster(6, 6, 0.34);
    parent.position.set(-2.4, 0.1, 0);
    var alpha = nucleonCluster(2, 2, 0.32);
    var alphaHome = new THREE.Vector3(-2.4, 0.15, 0.2);
    var alphaAway = new THREE.Vector3(2.6, 0.9, 0);
    alpha.position.copy(alphaHome);
    gfx.scene.add(parent, alpha);
    var t0 = performance.now();
    function restart() {
      t0 = performance.now();
    }
    function frame(now) {
      var fly = smoothstep(((now - t0) / 1000 - 0.15) / 1.05);
      alpha.position.lerpVectors(alphaHome, alphaAway, fly);
      alpha.children.forEach(function (ch) {
        ch.material.opacity = 1;
      });
      gfx.renderer.render(gfx.scene, gfx.camera);
      requestAnimationFrame(frame);
    }
    hostReplay(host, restart);
    requestAnimationFrame(frame);
    scenes["decay-a"] = { replay: restart };
  }

  function decayBeta(host) {
    var canvas = host.querySelector("canvas");
    var gfx = stage(canvas);
    var parent = nucleonCluster(5, 6, 0.34);
    parent.position.set(-2.4, 0.1, 0);
    var electron = ball(0.18, 0x2a62a8);
    var home = new THREE.Vector3(-2.4, 0.1, 0);
    var away = new THREE.Vector3(3.1, 0.35, 0);
    electron.position.copy(home);
    gfx.scene.add(parent, electron);
    var t0 = performance.now();
    function restart() {
      t0 = performance.now();
    }
    function frame(now) {
