      ray.material.opacity = 0.35 + 0.5 * Math.abs(Math.sin(t * 3 + idx));
    });
    gfx.renderer.render(gfx.scene, gfx.camera);
    requestAnimationFrame(frame);
  }
  hostReplay(host, restart);
  requestAnimationFrame(frame);
  scenes.tube = { replay: restart };
}

